/**
 * The private-domain scope model (plan §4).
 *
 * Private domains are EXPLICIT-ENTRY, and links between scopes are ONE-WAY:
 * a private note may link out to public notes; a public note never links in.
 * A note's scope comes from where it lives (its domain folder, or a
 * note-level `scope: private`) — never from who links to it.
 *
 * A private domain is opened ("unsealed") by exactly two signals:
 *   1. the session STARTED inside the domain's folder (session-start cwd only;
 *      a later `cd` is the model's to make and unlocks nothing);
 *   2. the person ran `/vault open <id|alias>`.
 * A prompt that merely names a sealed domain only PROPOSES the command — a
 * pasted page or injected text must not unseal anything.
 *
 * Opening a domain opens its linkGroup (the shard). Opening one private
 * domain never opens another. The scope truth lives in module memory only;
 * a reload re-seals everything.
 *
 * Pure — no `$`, no Node.
 */

export type DomainDef = {
  path?: string;
  scope?: string;
  linkGroup?: string;
  aliases?: string[];
};
export type DomainMap = Record<string, DomainDef>;

/** Shards that can never be opened in v2.0 (§3.6). */
export const UNOPENABLE = new Set(["loose", "quarantine"]);
export const MAIN = "main";

export function isPrivate(d: DomainDef | undefined): boolean {
  return d?.scope === "private";
}

/** Shard of a domain: `main` for public, linkGroup ?? id for private. */
export function shardOfDomain(domains: DomainMap, id: string): string {
  const d = domains[id];
  if (!isPrivate(d)) return MAIN;
  return d!.linkGroup || id;
}

/**
 * Shard of a note from its vault-relative path and its own frontmatter scope.
 * Longest domain path wins (nested domains). A note-level `scope: private` in
 * a public domain is `loose` (sealed, unopenable in v2.0); a `scope: public`
 * note inside a private domain stays private — the domain governs its path.
 */
export function shardOfNote(domains: DomainMap, relPath: string, noteScope?: string): string {
  let best: string | null = null;
  let bestLen = -1;
  for (const [id, d] of Object.entries(domains)) {
    const p = (d.path ?? "").replace(/\/+$/, "");
    if (!p) continue;
    if ((relPath === p || relPath.startsWith(`${p}/`)) && p.length > bestLen) {
      best = id;
      bestLen = p.length;
    }
  }
  const shard = best ? shardOfDomain(domains, best) : MAIN;
  if (shard === MAIN && noteScope === "private") return "loose";
  return shard;
}

export function isVisible(shard: string, open: ReadonlySet<string>): boolean {
  return shard === MAIN || (!UNOPENABLE.has(shard) && open.has(shard));
}

const strip = (p: string) => p.replace(/\/+$/, "");

/** Signal 1: shards whose folder contains the session-start cwd. */
export function openFromStartCwd(domains: DomainMap, vaultPath: string, startCwd: string): Set<string> {
  const open = new Set<string>();
  if (!vaultPath || !startCwd) return open;
  const cwd = strip(startCwd);
  for (const [id, d] of Object.entries(domains)) {
    if (!isPrivate(d) || !d.path) continue;
    const root = strip(`${strip(vaultPath)}/${d.path}`);
    if (cwd === root || cwd.startsWith(`${root}/`)) open.add(shardOfDomain(domains, id));
  }
  // A link group's home: starting in the folder that holds ALL of a group's
  // domains (`08 - Group/` above `08 - Group/Craft` and `08 - Group/World`)
  // is working on that group, so it opens — but only when every domain in
  // that folder belongs to the group, so a broad folder holding other
  // domains (`04 - Explorations/`) opens nothing. Never the vault root.
  const groups = new Map<string, { paths: string[][]; private: boolean }>();
  for (const d of Object.values(domains)) {
    if (!d.linkGroup || !d.path) continue;
    const g = groups.get(d.linkGroup) ?? { paths: [], private: false };
    g.paths.push(strip(d.path).split("/"));
    g.private ||= isPrivate(d);
    groups.set(d.linkGroup, g);
  }
  for (const [group, g] of groups) {
    if (!g.private || g.paths.length < 2) continue;
    const common: string[] = [];
    for (let i = 0; g.paths.every((p) => i < p.length && p[i] === g.paths[0][i]); i++) common.push(g.paths[0][i]);
    if (common.length === 0) continue;
    const prefix = common.join("/");
    const foreign = Object.values(domains).some(
      (d) => d.linkGroup !== group && d.path && (strip(d.path) === prefix || strip(d.path).startsWith(`${prefix}/`)),
    );
    if (foreign) continue;
    const home = strip(`${strip(vaultPath)}/${prefix}`);
    if (cwd === home || cwd.startsWith(`${home}/`)) open.add(group);
  }
  return open;
}

/**
 * Signal 2: `/vault open <ref>` — exact id (case-insensitive) or a configured
 * alias. Only private domains resolve: a public domain needs no opening, and
 * an unknown ref gets the same answer as a public one so the reply cannot be
 * used to probe for sealed ids.
 */
export function resolveOpenRef(domains: DomainMap, ref: string): { shard: string; domain: string } | null {
  const r = ref.trim().toLowerCase();
  if (!r) return null;
  for (const [id, d] of Object.entries(domains)) {
    if (!isPrivate(d)) continue;
    if (id.toLowerCase() === r || (d.aliases ?? []).some((a) => a.toLowerCase() === r)) {
      return { shard: shardOfDomain(domains, id), domain: id };
    }
  }
  return null;
}

/** Prompt origins that count as the person typing (d.ts PromptOrigin). */
export const TYPED_ORIGINS = new Set(["composer", "bridge"]);
const PROPOSE_WINDOW = 200;

/**
 * Domains a typed prompt names that are currently sealed — to PROPOSE
 * `/vault open`, never to open. Whole-word match within the first 200 typed
 * characters (a long paste mentioning the name further down does not count),
 * ids of ≥4 characters (with `-`/`_` read as spaces) and configured aliases.
 */
export function proposeFromPrompt(
  domains: DomainMap,
  text: string,
  originKind: string,
  open: ReadonlySet<string>,
): string[] {
  if (!TYPED_ORIGINS.has(originKind)) return [];
  const hay = ` ${String(text ?? "").slice(0, PROPOSE_WINDOW).toLowerCase()} `;
  const word = (needle: string) => {
    const n = needle.toLowerCase().trim();
    if (!n) return false;
    const esc = n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/[-_ ]+/g, "[-_ ]+");
    return new RegExp(`(^|[^a-z0-9])${esc}([^a-z0-9]|$)`).test(hay);
  };
  const out: string[] = [];
  for (const [id, d] of Object.entries(domains)) {
    if (!isPrivate(d)) continue;
    const shard = shardOfDomain(domains, id);
    if (open.has(shard)) continue;
    const names = [...(id.length >= 4 ? [id] : []), ...(d.aliases ?? [])];
    if (names.some(word)) out.push(id);
  }
  return out;
}

/**
 * Absolute roots the sealing guard denies: every private domain folder whose
 * shard is not open, plus `<vault>/.wiki/sealed` (always — the model never
 * reads sealed artefacts, open or not; commonplace serves them).
 */
export function sealedRoots(domains: DomainMap, vaultPath: string, open: ReadonlySet<string>): string[] {
  const v = strip(vaultPath);
  const roots = [`${v}/.wiki/sealed`];
  for (const [id, d] of Object.entries(domains)) {
    if (!isPrivate(d) || !d.path) continue;
    if (isVisible(shardOfDomain(domains, id), open)) continue;
    roots.push(strip(`${v}/${d.path}`));
  }
  return roots;
}

export function protectedRoots(vaultPath: string): string[] {
  const v = strip(vaultPath);
  return [`${v}/.wiki/skills`, `${v}/.wiki/agents`];
}

/** Public domain ids — the only ones any listing may name while sealed. */
export function listableDomains(domains: DomainMap, open: ReadonlySet<string>): string[] {
  return Object.keys(domains)
    .filter((id) => isVisible(shardOfDomain(domains, id), open))
    .sort();
}

files.hooks/lib/core/vault-guard.ts:
/**
 * The built-in-tool guard, as one pure decision over every registered vault
 * (plan §4.2, §4.2a, §2.3b step 1). `register.tsx` gathers the facts — the
 * registry, each vault's `domains.json`, the open shards held in module
 * memory, `sealed/names.json` — and asks three questions here:
 *
 *   1. `sealRootsFor`: which absolute folders the model's file tools may not
 *      reach (fed to `checkSealedAccess`).
 *   2. `sanitizeWrite`: does a Write/Edit into a SOURCE note carry a remote
 *      image embed or an over-length URL? Strip them on the way down, so no
 *      file is ever rewritten after the fact.
 *   3. `leakVerdict`: does a write reproduce a private title somewhere that
 *      title must not go?
 *
 * Pure — no `$`, no Node. Every caller wraps these in try/catch and fails
 * open; a guard bug must never block a tool call.
 */

import {
  sealedRoots,
  protectedRoots,
  shardOfNote,
  isVisible,
  isPrivate,
  MAIN,
  type DomainMap,
} from "./scope.js";
import { normalizePath, isUnder, type SealRoots } from "./seal.js";
import { sanitizeIngestedBody, splitFrontmatterRaw } from "../index/sanitize.js";
import { checkSealedLeak, type SealedName } from "../guard.js";

export type GuardVault = {
  /** The registered path, normalised. */
  path: string;
  /** Where it lands when it differs (`$.fs.stat` realPath), else absent. */
  real?: string;
  domains: DomainMap;
  /** Registry id, label and aliases (absent in tests that only exercise paths). */
  id?: string;
  label?: string;
  aliases?: string[];
  isPrivate?: boolean;
};

export type OpenOf = (vaultPath: string) => ReadonlySet<string>;

const strip = (p: string) => p.replace(/\/+$/, "");

/** Both spellings of a vault: registered and resolved. */
const spellings = (v: GuardVault) => [...new Set([strip(v.path), ...(v.real ? [strip(v.real)] : [])])];

/** `sealedRoots` always lists `.wiki/sealed`; anything more is a sealed domain. */
const anySealed = (v: GuardVault, open: ReadonlySet<string>) =>
  sealedRoots(v.domains, v.path, open).length > 1;

/**
 * Seal roots for every vault. `.wiki/sealed` is always under-denied (the
 * model never reads sealed artefacts; commonplace serves them), but it only
 * makes the vault ROOT un-scannable while some domain is actually sealed —
 * the user's rule (Q9): root greps are denied while any domain is sealed, and
 * a vault with nothing sealed keeps working as a plain folder.
 */
export function sealRootsFor(vaults: readonly GuardVault[], openOf: OpenOf): SealRoots {
  const sealed: string[] = [];
  const noScan: string[] = [];
  const protectedWrite: string[] = [];
  for (const v of vaults) {
    const open = openOf(v.path);
    const scanBlocked = anySealed(v, open);
    for (const base of spellings(v)) {
      const roots = sealedRoots(v.domains, base, open);
      const wikiSealed = `${base}/.wiki/sealed`;
      for (const r of roots) {
        if (r === wikiSealed && !scanBlocked) noScan.push(r);
        else sealed.push(r);
      }
      protectedWrite.push(...protectedRoots(base));
    }
  }
  return { sealed, protectedWrite, sealedNoScan: noScan };
}

/** The vault a path lies in, and the path relative to it. */
export function locate(
  vaults: readonly GuardVault[],
  absPath: string,
): { vault: GuardVault; rel: string } | null {
  let best: { vault: GuardVault; rel: string; len: number } | null = null;
  for (const v of vaults) {
    for (const base of spellings(v)) {
      if (!isUnder(absPath, base) || absPath === base) continue;
      if (!best || base.length > best.len) best = { vault: v, rel: absPath.slice(base.length + 1), len: base.length };
    }
  }
  return best ? { vault: best.vault, rel: best.rel } : null;
}

/** A source note: a `.md` under some registered domain folder, outside `.wiki/`. */
export function isSourceNotePath(v: GuardVault, rel: string): boolean {
  if (!rel.endsWith(".md") || rel === ".wiki" || rel.startsWith(".wiki/")) return false;
  return Object.values(v.domains).some((d) => {
    const p = strip(d.path ?? "");
    return !!p && rel.startsWith(`${p}/`);
  });
}

/**
 * Sanitise a Write/Edit into a source note on the way down.
 * Returns the replacement fields and what was stripped, or null when the
 * write is not a source-note write or nothing needed stripping. Frontmatter
 * is never touched (a `source:` URL there is metadata, not a rendered link).
 */
export function sanitizeWrite(
  tool: string,
  input: Record<string, unknown>,
  vaults: readonly GuardVault[],
  cwd: string,
): { patch: Record<string, string>; stripped: string[] } | null {
  const field = tool === "Write" ? "content" : tool === "Edit" ? "new_string" : "";
  if (!field) return null;
  const target = typeof input.file_path === "string" ? normalizePath(input.file_path, cwd) : "";
  const text = typeof input[field] === "string" ? (input[field] as string) : "";
  if (!target || !text) return null;
  const at = locate(vaults, target);
  if (!at || !isSourceNotePath(at.vault, at.rel)) return null;
  const { frontmatterBlock, body } = splitFrontmatterRaw(text);
  const { body: clean, stripped } = sanitizeIngestedBody(body);
  if (stripped.length === 0) return null;
  return { patch: { [field]: frontmatterBlock + clean }, stripped };
}

const LEAK_FIELDS: Record<string, string> = { Write: "content", Edit: "new_string", NotebookEdit: "new_source" };

/**
 * Leak verdict for a write. `names` is the union of every registered vault's
 * private titles, each stamped with its `vault` path.
 *
 * - Outside every vault: any private title (prose or link) is checked. The
 *   caller decides whether such a write is in scope at all (today: only in a
 *   code repository).
 * - Inside a vault: names of the SAME shard are the target's own material and
 *   pass; names from another shard of the same vault are checked for explicit
 *   `[[links]]` only — a link from public (or another private group) into a
 *   private note is the one-way violation; a phrase is not worth a deny there.
 *   Names from another vault are checked fully (B13).
 * - Writes into `.wiki/` (indexes, logs) are commonplace's own and pass.
 */
/**
 * Leak-guard shard carrying every title of a vault registered `isPrivate`.
 * Never openable; guards writes OUTSIDE that vault only.
 */
export const PRIVATE_VAULT_SHARD = "private-vault";

export function leakVerdict(
  tool: string,
  input: Record<string, unknown>,
  vaults: readonly GuardVault[],
  names: readonly SealedName[],
  openOf: OpenOf,
  cwd: string,
): { deny: string } | null {
  const field = LEAK_FIELDS[tool];
  if (!field || names.length === 0) return null;
  const text = typeof input[field] === "string" ? (input[field] as string) : "";
  const rawTarget = typeof input.file_path === "string" ? input.file_path : typeof input.notebook_path === "string" ? input.notebook_path : "";
  if (!text || !rawTarget) return null;
  const isOpen = (n: SealedName) => isVisible(n.shard, n.vault ? openOf(n.vault) : new Set<string>());
  const at = locate(vaults, normalizePath(rawTarget, cwd));
  if (!at) return checkSealedLeak(text, names, isOpen);
  if (at.rel.startsWith(".wiki/")) return null;
  const targetShard = shardOfNote(at.vault.domains, at.rel);
  const same = (n: SealedName) => n.vault === at.vault.path;
  const foreign = names.filter((n) => !same(n));
  const otherShard = names.filter((n) => same(n) && n.shard !== targetShard && n.shard !== PRIVATE_VAULT_SHARD);
  return (
    checkSealedLeak(text, foreign, isOpen) ??
    checkSealedLeak(text, otherShard, isOpen, { linksOnly: true })
  );
}

/** Legacy fallback: private titles derived from the v1 jsonl records. */
export function namesFromLegacy(
  records: readonly Record<string, unknown>[],
  domains: DomainMap,
  vault: string,
): SealedName[] {
  const out: SealedName[] = [];
  for (const r of records) {
    if (r.scope !== "private") continue;
    const t = String(r.title ?? r.name ?? "").trim();
    if (!t) continue;
    const dom = r.domain ? String(r.domain) : "";
    const shard = dom && isPrivate(domains[dom]) ? domains[dom].linkGroup || dom : "loose";
    out.push({ t, shard: shard === MAIN ? "loose" : shard, vault });
  }
  return out;
}

